@ConfigurationProperties(prefix = "tiffin")
@Validated
public record TiffinProperties(
        @NotBlank String name,
        @Min(1) int maxOrdersPerDay,
        Delivery delivery,
        @DefaultValue("2h") Duration orderCutoff) {

    public record Delivery(int fee, int radiusKm) {}
}
