  and id <> all (array['tq-sb-spring-boot-actuator-1', 'tq-sb-spring-boot-actuator-2', 'tq-sb-spring-boot-actuator-3', 'tq-sb-spring-boot-actuator-4', 'tq-sb-spring-boot-actuator-5']);

-- ===========================================================================
-- VALIDATION — fail loudly if this batch did not land exactly.
-- ===========================================================================
do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb195$configuration/application-properties-vs-application-yml$sb195$, $sb196$configuration/value-annotation$sb196$, $sb197$configuration/configuration-properties$sb197$, $sb198$configuration/externalized-configuration$sb198$, $sb199$configuration/logging-in-spring-boot$sb199$, $sb200$configuration/spring-boot-actuator$sb200$);
  if v_topics <> 6 then raise exception 'validation: expected 6 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb195$configuration/application-properties-vs-application-yml$sb195$, $sb196$configuration/value-annotation$sb196$, $sb197$configuration/configuration-properties$sb197$, $sb198$configuration/externalized-configuration$sb198$, $sb199$configuration/logging-in-spring-boot$sb199$, $sb200$configuration/spring-boot-actuator$sb200$);
  if v_lessons <> 6 then raise exception 'validation: expected 6 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 6 then raise exception 'validation: expected 6 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-application-properties-vs-application-yml', 'pt-sb-value-annotation', 'pt-sb-configuration-properties', 'pt-sb-externalized-configuration', 'pt-sb-logging-in-spring-boot', 'pt-sb-spring-boot-actuator') and learning_topic_id is not null;
  if v_tests <> 6 then raise exception 'validation: expected 6 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-application-properties-vs-application-yml', 'pt-sb-value-annotation', 'pt-sb-configuration-properties', 'pt-sb-externalized-configuration', 'pt-sb-logging-in-spring-boot', 'pt-sb-spring-boot-actuator');
  if v_questions <> 30 then raise exception 'validation: expected 30 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0134/105 OK: Spring Boot Tutorial batch 05: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

notify pgrst, 'reload schema';
